<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import WorldRecords from './WorldRecords.vue'
import ArchivePageHeader from '../../../desktop/src/renderer/ui/ArchivePageHeader.vue'
import type { BookApi, DefinitionTypes } from '../api/writing'
import { messageOf } from '../api/http'
import { DraftStore } from './drafts'
const props = defineProps<{ api: BookApi; owner: string; kind: 'profile' | 'world' }>()
const data = reactive<Partial<DefinitionTypes>>({}), revisions = reactive<Record<string, string>>({}), saved = ref(''), busy = ref(false), loading = ref(true), error = ref(''), notice = ref('')
const store = new DraftStore(sessionStorage, props.owner, props.api.id), recovery = ref<Partial<DefinitionTypes> | null>(null)
const keys = props.kind === 'profile' ? ['profile'] as const : ['foundation', 'realms', 'system-template', 'power-system', 'cheat-system'] as const
const dirty = computed(() => !loading.value && JSON.stringify(data) !== saved.value)
watch(data, () => { if (!loading.value && dirty.value) { try { store.write(props.kind, saved.value, data) } catch { error.value = '浏览器恢复空间不足，请及时保存或复制当前设定。' } } }, { deep: true, flush: 'sync' })
onMounted(async () => { try { for (const key of keys) { const result = await props.api.definition(key); Object.assign(data, { [key]: result.data }); revisions[key] = result.revision }
  saved.value = JSON.stringify(data); const copy = store.read<Partial<DefinitionTypes>>(props.kind); if (copy && JSON.stringify(copy.data) !== saved.value) recovery.value = copy.data
} catch (e) { error.value = messageOf(e) } finally { loading.value = false } })
function addRealm() { data.realms?.levels.push({ id: crypto.randomUUID(), name: '', description: '' }) }
function restore() { if (recovery.value) Object.assign(data, recovery.value); recovery.value = null; notice.value = '恢复内容尚未保存，请核对后保存。' }
async function save() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''
  try { if (data.profile) data.profile.targetWords = data.profile.plannedVolumes * data.profile.chaptersPerVolume * data.profile.targetWordsPerChapter
    const snapshot = structuredClone(JSON.parse(JSON.stringify(data))) as Partial<DefinitionTypes>
    for (const key of keys) { const value = snapshot[key]; if (!value) continue; const result = await props.api.saveDefinition(key, value, revisions[key]!); revisions[key] = result.revision; if (JSON.stringify(data[key]) === JSON.stringify(value)) Object.assign(data, { [key]: result.data }); else if (key === 'profile' && data.profile) data.profile.revision = (result.data as DefinitionTypes['profile']).revision; Object.assign(snapshot, { [key]: result.data }) }
    saved.value = JSON.stringify(snapshot); if (!dirty.value) store.remove(props.kind); notice.value = '已保存到当前作品。'
  } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
</script>
<template><section class="form-page"><ArchivePageHeader :eyebrow="kind === 'profile' ? '01 / DEFINITION' : '02 / WORLD ARCHIVE'" :title="kind === 'profile' ? '定书' : '世界设定'" :description="kind === 'profile' ? '先确定故事的方向，再慢慢展开世界。' : '正式设定会进入当前作品的生成与审校上下文。'"><span class="muted">{{ dirty ? '有未保存的修改' : '与已保存版本一致' }}</span><button class="primary" :disabled="loading || busy" @click="save">{{ busy ? '保存中…' : '保存设定' }}</button></ArchivePageHeader><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status" class="success">{{ notice }}</p><aside v-if="recovery" class="recovery-note"><b>此标签页保留了一份未保存的设定</b><p>恢复后请核对；当前服务端版本不会被自动覆盖。</p><button @click="restore">恢复到表单</button><button @click="recovery = null">暂不恢复</button></aside><p v-if="loading" role="status">正在读取设定…</p><form v-else class="definition-form" @submit.prevent="save"><template v-if="kind === 'profile' && data.profile"><label class="premise-field">核心设想<textarea v-model="data.profile.coreIdea" rows="5" placeholder="主角是谁，遇到了什么？你最想写的反差是什么？"></textarea></label><div class="form-row"><label>小说题材<input v-model="data.profile.genre" placeholder="例如：玄幻、悬疑、都市"></label><label>细分类<input v-model="data.profile.subgenre" placeholder="可选"></label></div><fieldset><legend>篇幅计划</legend><div class="form-row three"><label>计划卷数<input v-model.number="data.profile.plannedVolumes" type="number" min="1" max="100"></label><label>每卷章节<input v-model.number="data.profile.chaptersPerVolume" type="number" min="1" max="500"></label><label>每章目标字数<input v-model.number="data.profile.targetWordsPerChapter" type="number" min="300" max="50000" step="100"></label></div></fieldset><div class="form-row"><label>叙述视角<input v-model="data.profile.defaultPov" placeholder="例如：第三人称有限视角"></label><label>目标读者<input v-model="data.profile.audienceScale"></label></div><label>写作风格<textarea v-model="data.profile.writingStyle" rows="3"></textarea></label><label>审校要求<select v-model="data.profile.reviewStrictness"><option value="balanced">均衡</option><option value="strict">严格</option></select></label><p class="muted">正文生成包含完整审校。AI 返回候选稿，由你决定是否采用。</p></template><template v-else-if="data.foundation"><label>世界观<textarea v-model="data.foundation.worldView" rows="8" placeholder="时代、地域、社会规则，以及这个世界不可逾越的边界。"></textarea></label><label>作者札记<textarea v-model="data.foundation.sourceNotes" rows="4" placeholder="可以随时补充你的灵感和资料。"></textarea></label><label v-if="data['power-system']">力量体系总述<textarea v-model="data['power-system'].overview" rows="3"></textarea></label><label class="check-label"><input v-model="data.foundation.useRealms" type="checkbox">启用境界 / 实力表</label><fieldset v-if="data.foundation.useRealms && data.realms"><legend>自定义境界</legend><div v-for="(level, index) in data.realms.levels" :key="level.id" class="realm-row"><label>境界名称<input v-model="level.name"></label><label>能力与限制<input v-model="level.description"></label><button type="button" :aria-label="`移除境界 ${level.name || index + 1}`" @click="data.realms.levels.splice(index, 1)">移除</button></div><button type="button" @click="addRealm()">＋ 添加境界</button></fieldset><label v-if="data['cheat-system']">金手指 / 特殊优势<textarea v-model="data['cheat-system'].overview" rows="3"></textarea></label><label class="check-label"><input v-model="data.foundation.useSystem" type="checkbox">启用固定系统界面模板</label><label v-if="data.foundation.useSystem && data['system-template']">系统界面模板<textarea aria-label="系统界面模板" v-model="data['system-template'].template" rows="7" placeholder="[属性]&#10;[技能]&#10;[任务]"></textarea><small>AI 描写系统弹窗时，会沿用这份固定格式。</small></label></template><button class="primary" :disabled="busy || loading">保存设定</button></form><WorldRecords v-if="kind === 'world'" :api="api" :owner="owner" /></section></template>
